70	// Not sensitive, and browsers request these before/without any session
71	// (a fresh tab, the login page itself, Safari's separate cookie jar, ...) -
72	// serving the login-page HTML instead of the real file for these specific
73	// paths is what made the favicon silently break for anyone not already
74	// authenticated in that browser. Every other static asset (styles.css,
75	// js/app.js, ...) is correctly still gated - this is a narrow bypass.
76	const PUBLIC_PATHS = new Set(['/favicon.svg', '/favicon-192.png', '/favicon-32.png']);
77	
78	// Timing-safe compare, same reasoning as local-claude-agent's own token
79	// check (server.js timingSafeEqual) - a static token is worth comparing in
80	// constant time rather than with a plain ===.
81	function tokenMatches(provided, expected) {
82	    if (!expected || !provided) return false;
83	    const a = Buffer.from(String(provided));
84	    const b = Buffer.from(String(expected));
85	    if (a.length !== b.length) return false;
86	    return crypto.timingSafeEqual(a, b);
87	}
88	
89	// Lets machine callers (the Generator/Researcher/Insights Claude routines -
90	// see server/routes/agentResearcher.js and docs/insights-agent-routine.md)
91	// authenticate without a browser session cookie once ADMIN_EMAIL/etc. lock
92	// the hub down for everyone else. Optional: unset AGENT_API_TOKEN and this
93	// path simply never matches, same graceful-no-op shape as every other
94	// optional integration in this codebase. A routine sends
95	// `Authorization: Bearer <AGENT_API_TOKEN>` instead of logging in.
96	const AGENT_API_TOKEN = process.env.AGENT_API_TOKEN || '';
97	
98	function isAgentTokenRequest(req) {
99	    const header = req.headers['authorization'] || '';
100	    const provided = header.startsWith('Bearer ') ? header.slice(7) : '';
101	    return tokenMatches(provided, AGENT_API_TOKEN);
102	}
103	
104	// Gates every request. Left permanently open (no-op) if auth isn't
105	// configured (ADMIN_EMAIL/ADMIN_PASSWORD_HASH/SESSION_SECRET unset), so the
106	// app keeps working exactly as before for local dev where nobody's set
107	// those env vars - the hub is only actually locked down once they're set in
108	// production.
109	export function requireAuth(req, res, next) {
110	    if (!isAuthConfigured()) return next();
111	    if (req.path === '/api/auth/login' || PUBLIC_PATHS.has(req.path)) return next();
112	    if (isAgentTokenRequest(req)) return next();
113	    if (isRequestAuthenticated(req)) return next();
114	
115	    if (req.path.startsWith('/api/')) {
116	        return res.status(401).json({ error: 'unauthorized' });
117	    }
118	    res.status(200).type('html').send(LOGIN_PAGE);
119	}
